describe('isValidEmail', () => {
  it('should return true for valid email addresses', () => {
    expect(isValidEmail('user@example.com')).toBe(true);
    expect(isValidEmail('john.doe+tag@company.co.uk')).toBe(true);
    expect(isValidEmail('a@b.c')).toBe(true);
  });

  it('should return false for invalid email addresses', () => {
    expect(isValidEmail('invalid.email')).toBe(false);
    expect(isValidEmail('@example.com')).toBe(false);
    expect(isValidEmail('user@')).toBe(false);
    expect(isValidEmail('user@.com')).toBe(false);
    expect(isValidEmail('user @example.com')).toBe(false);
  });

  it('should return false for empty string', () => {
    expect(isValidEmail('')).toBe(false);
  });

  it('should return false for whitespace', () => {
    expect(isValidEmail('   ')).toBe(false);
  });
});

describe('sanitizeInput', () => {
  it('should escape HTML tags', () => {
    expect(sanitizeInput('<script>alert("xss")</script>')).toBe('&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;');
    expect(sanitizeInput('<img src=x onerror=alert(1)>')).toBe('&lt;img src=x onerror=alert(1)&gt;');
  });

  it('should escape all dangerous characters', () => {
    expect(sanitizeInput('"quoted"')).toBe('&quot;quoted&quot;');
    expect(sanitizeInput("'single'quoted'")).toBe('&#039;single&#039;quoted&#039;');
  });

  it('should handle multiple dangerous characters', () => {
    expect(sanitizeInput('<div onclick="alert(\'xss\')">')).toBe('&lt;div onclick=&quot;alert(&#039;xss&#039;)&quot;&gt;');
  });

  it('should preserve safe content', () => {
    expect(sanitizeInput('John Doe')).toBe('John Doe');
    expect(sanitizeInput('user@example.com')).toBe('user@example.com');
  });

  it('should handle empty string', () => {
    expect(sanitizeInput('')).toBe('');
  });
});

describe('createUser', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should create a user with valid input', async () => {
    const input = { email: 'john@example.com', name: 'John Doe' };
    const user = await createUser(input);

    expect(user.id).toBeDefined();
    expect(user.id).toMatch(/^user_\d+_[a-z0-9]+$/);
    expect(user.email).toBe('john@example.com');
    expect(user.name).toBe('John Doe');
    expect(user.createdAt).toBeInstanceOf(Date);
  });

  it('should lowercase email addresses', async () => {
    const input = { email: 'JOHN@EXAMPLE.COM', name: 'John Doe' };
    const user = await createUser(input);
    expect(user.email).toBe('john@example.com');
  });

  it('should sanitize user name input', async () => {
    const input = { email: 'john@example.com', name: '<script>alert("xss")</script>' };
    const user = await createUser(input);
    expect(user.name).toBe('&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;');
  });

  it('should throw error when email is missing', async () => {
    const input = { email: '', name: 'John Doe' };
    await expect(createUser(input)).rejects.toThrow('Email and name are required');
  });

  it('should throw error when name is missing', async () => {
    const input = { email: 'john@example.com', name: '' };
    await expect(createUser(input)).rejects.toThrow('Email and name are required');
  });

  it('should throw error when both email and name are missing', async () => {
    const input = { email: '', name: '' };
    await expect(createUser(input)).rejects.toThrow('Email and name are required');
  });

  it('should throw error for invalid email format', async () => {
    const input = { email: 'invalid-email', name: 'John Doe' };
    await expect(createUser(input)).rejects.toThrow('Invalid email format');
  });

  it('should handle special characters in name', async () => {
    const input = { email: 'john@example.com', name: 'José María' };
    const user = await createUser(input);
    expect(user.name).toBe('José María');
  });
});

describe('generateId', () => {
  it('should generate a valid ID format', () => {
    const id = generateId();
    expect(id).toMatch(/^user_\d+_[a-z0-9]+$/);
  });

  it('should generate unique IDs', () => {
    const ids = new Set();
    for (let i = 0; i < 100; i++) {
      ids.add(generateId());
    }
    expect(ids.size).toBe(100);
  });

  it('should start with user_ prefix', () => {
    const id = generateId();
    expect(id.startsWith('user_')).toBe(true);
  });
});

describe('saveUser', () => {
  let mockDb: jest.Mock;

  beforeEach(() => {
    mockDb = jest.fn().mockResolvedValue(undefined);
    // Mock database module
    jest.mock('./db', () => ({
      query: mockDb
    }));
  });

  it('should call database with parameterized query', async () => {
    const user: User = {
      id: 'user_123_abc',
      email: 'john@example.com',
      name: 'John Doe',
      createdAt: new Date('2024-01-01')
    };

    await saveUser(user);

    expect(mockDb).toHaveBeenCalledWith(
      'INSERT INTO users (id, email, name, created_at) VALUES ($1, $2, $3, $4)',
      [user.id, user.email, user.name, user.createdAt]
    );
  });

  it('should use parameterized query to prevent SQL injection', async () => {
    const user: User = {
      id: 'user_123',
      email: "test@example.com'; DROP TABLE users; --",
      name: 'Hacker',
      createdAt: new Date()
    };

    await saveUser(user);

    // Verify parameters are passed separately, not concatenated into query
    expect(mockDb).toHaveBeenCalledWith(
      expect.stringContaining('$1, $2, $3, $4'),
      expect.arrayContaining([user.email])
    );
  });
});

describe('createUser - email edge cases', () => {
  it('should handle emails with numbers and special chars', async () => {
    const input = { email: 'user+tag123@sub-domain.co.uk', name: 'Test User' };
    const user = await createUser(input);
    expect(user.email).toBe('user+tag123@sub-domain.co.uk');
  });

  it('should reject emails with consecutive dots', async () => {
    const input = { email: 'user..name@example.com', name: 'Test User' };
    await expect(createUser(input)).rejects.toThrow('Invalid email format');
  });

  it('should handle very long valid email addresses', async () => {
    const longEmail = 'a'.repeat(64) + '@' + 'b'.repeat(63) + '.com';
    const input = { email: longEmail, name: 'Test User' };
    const user = await createUser(input);
    expect(user.email).toBe(longEmail);
  });
});

describe('sanitizeInput - edge cases', () => {
  it('should handle already escaped entities', () => {
    expect(sanitizeInput('&lt;tag&gt;')).toBe('&amp;lt;tag&amp;gt;');
  });

  it('should handle null bytes and control characters', () => {
    // Should not crash with unusual input
    expect(() => sanitizeInput('test\x00data')).not.toThrow();
  });

  it('should handle very long strings', () => {
    const longString = '<script>' + 'a'.repeat(10000) + '</script>';
    const result = sanitizeInput(longString);
    expect(result).toContain('&lt;script&gt;');
    expect(result.length).toBeGreaterThan(longString.length);
  });
});

